def _clean_expired(self):
    """
    Goes through all messages and groups and removes those that are expired.
    Any channel with an expired message is removed from all groups.
    """
    now = time.time()

    # Find expired messages and collect channels to remove
    channels_to_remove = set()
    for channel, queue in list(self.channels.items()):
        # Create new queue with only unexpired messages
        new_queue = asyncio.Queue(maxsize=self.get_capacity(channel))
        expired = False

        # Check all messages in the queue
        while not queue.empty():
            try:
                expiry, message = queue.get_nowait()
                if expiry > now:
                    # If not expired, keep it
                    new_queue.put_nowait((expiry, message))
                else:
                    expired = True
            except (asyncio.QueueEmpty, asyncio.QueueFull):
                break

        # If we found an expired message, remove channel from all groups
        if expired:
            channels_to_remove.add(channel)

        # If the new queue is empty, remove the channel
        if new_queue.empty():
            self.channels.pop(channel, None)
        else:
            # Otherwise replace with the clean queue
            self.channels[channel] = new_queue

    # Remove channels with expired messages from all groups
    for channel in channels_to_remove:
        self._remove_from_groups(channel)

    # Remove expired group memberships
    group_expiry = now - self.group_expiry
    for group_name, channels in list(self.groups.items()):
        for channel, added in list(channels.items()):
            # If membership is expired, remove it
            if added and added < group_expiry:
                channels.pop(channel, None)

        # If group is empty, remove it
        if not channels:
            self.groups.pop(group_name, None)
# Flush extension

async def flush(self):
    self.channels = {}
    self.groups = {}

async def close(self):
    # Nothing to go
    pass
